resultado = {}
for archivo, tok in pares:
    try:
        req = urllib.request.Request(B + tok, data=open(archivo, "rb").read(), method="POST",
                                     headers={"Content-Type": "application/octet-stream", "User-Agent": "curl/8.0"})
        with urllib.request.urlopen(req, timeout=180) as r:
            resultado[archivo] = json.loads(r.read().decode())["mediaId"]
        print("OK", archivo, resultado[archivo])
    except Exception as e:
        print("ERROR", archivo, e)

with open("ids_hr.json", "w", encoding="utf-8") as f:
    json.dump(resultado, f, ensure_ascii=False, indent=1)
